        "content": "package authz

import future.keywords.if
import future.keywords.in

default allowed := false
default withinTheAuthenticationFailureLimit = false
default withinPendingVsCompletedAuthLimit = false
currentSystemTime := time.now_ns()/1000000

authFailureCount = count([i | i = input.events[_]; checkForAuthFailuresAgainstConfigurations(i)])
failedEventIds = ([(i.id) | i = input.events[_]; checkForAuthFailuresAgainstConfigurations(i)])

inProgressAuthEventCount = count({y | some y in input.events; checkForInProgressAuthCount(y)})
completedAuthEventCount = count({y | some y in input.events; checkForCompletedAuthCount(y)})

default allowedAuthenticators := ["QR"]

oob_auth_events := ["OOB_WEBSITE_AUTH", "OOB_WEBSITE_TRANS"]
qr_auth_events := ["QR_FALLBACK_PAYLOAD_RETRIEVED", "SESSION_WEBSITE_AUTH"]
fido2_auth_events := ["FIDO2_WEBAUTHN", "SMARTKEY_AUTH"]

qrBlocked := array.concat(oob_auth_events, qr_auth_events)
fido2Blocked := array.concat(qrBlocked, fido2_auth_events)

default eventNamesForFailureCheck := ["OOB_WEBSITE_AUTH", "OOB_WEBSITE_TRANS"]
eventNamesForFailureCheck := fido2Blocked if {
not "QR" in allowedAuthenticators
not "FIDO2" in allowedAuthenticators
}
else := qrBlocked if not "QR" in allowedAuthenticators

withinTheAuthenticationFailureLimit if {
listOfAuthFailureEvents = {y | some y in input.events; checkForAuthFailuresAgainstConfigurations(y)}
count(listOfAuthFailureEvents) <= 5
}

hasBeenWhitelistByAdmin if {
count({y | some y in input.events; checkForWhitelist(y)}) > 0
}

userCurrentlyBlocked if {
count({y | some y in input.events; checkForUserBlockedEvent(y)}) > 0
}

containing_auth_event_name(eventName, eventListReference) {
eventName in eventListReference
}

checkAgainstConfiguredTimeframe(eventTime) if {
timeDifferenceMillis = currentSystemTime-(to_number(eventTime))
timeDifferenceMillis < 60 * 1000 * 10
}

checkAgainstBlockedUserWindow(eventTime) if {
timeDifferenceMillis = currentSystemTime-(to_number(eventTime))
timeDifferenceMillis < 60 * 1000 * 30
}

checkForAuthFailuresAgainstConfigurations(event) if {
eventTimeParsed = to_number(event.eventTimeInUTC)

event.isSuccessful == false
checkAgainstConfiguredTimeframe(eventTimeParsed)
containing_auth_event_name(event.eventName, eventNamesForFailureCheck)
}

checkForInProgressAuthCount(event) if {
inProgressAuthEvents := ["OOB_WEBSITE_AUTH", "SESSION_WEBSITE_AUTH", "FIDO2_WEBAUTHN", "SMARTKEY_AUTH"]
eventTimeParsed = to_number(event.eventTimeInUTC)
checkAgainstConfiguredTimeframe(eventTimeParsed)
containing_auth_event_name(event.eventName, inProgressAuthEvents)
}

checkForCompletedAuthCount(event) if {
authCompleteEvents := ["OOB_WEBSITE_AUTH_COMPLETE", "SESSION_WEBSITE_AUTH_COMPLETE", "FIDO2_WEBAUTHN_COMPLETE", "SMARTKEY_AUTH_COMPLETE"]
eventTimeParsed = to_number(event.eventTimeInUTC)

checkAgainstConfiguredTimeframe(eventTimeParsed)
event.eventName in authCompleteEvents
}

withinPendingVsCompletedAuthLimit if {
inProgressAuthEventCount - completedAuthEventCount <= 5
}

checkForWhitelist(event) if {
# Converted event time from milliseconds to nanoseconds for proper comparison
eventTimeParsed = to_number(event.eventTimeInUTC)
checkAgainstConfiguredTimeframe(eventTimeParsed)

event.eventName == "ADAPT_POLICY_EVAL_USER_WHITELISTED"
}

checkForUserBlockedEvent(event) if {
# Converted event time from milliseconds to nanoseconds for proper comparison
eventTimeParsed = to_number(event.eventTimeInUTC)
checkAgainstBlockedUserWindow(eventTimeParsed)

event.eventName == "ADAPT_POLICY_EVAL_USER_BLOCKED"
}

allowed if {
withinTheAuthenticationFailureLimit
withinPendingVsCompletedAuthLimit
not userCurrentlyBlocked
}

# Message for whitelisted user exempt from policy evaluation
message = "Policy evaluation has failed but user is whitelisted" if {
not withinTheAuthenticationFailureLimit
hasBeenWhitelistByAdmin
}

# Outside of logic above force allowed if user is currently whitelisted by admin
allowed if {
hasBeenWhitelistByAdmin
}

# Successful message response
message = "Policy evaluation successful" if {
withinTheAuthenticationFailureLimit
withinPendingVsCompletedAuthLimit
not userCurrentlyBlocked
}

# Msg out when user is blocked because of authentication limit being reached
message = "Policy evaluation has failed, user currently blocked because of too many authentication failures" if {
not withinTheAuthenticationFailureLimit
not hasBeenWhitelistByAdmin
userCurrentlyBlocked
} else := "Policy evaluation has failed, user currently blocked because they have gone over their pending authentication limit" if {
not withinPendingVsCompletedAuthLimit
not hasBeenWhitelistByAdmin
userCurrentlyBlocked
}

# Blocked message triggered by both checks failing
message = "Policy evaluation has failed, user currently blocked. User has too many failed auth and pending attempts" if {
not withinPendingVsCompletedAuthLimit
not withinTheAuthenticationFailureLimit
not hasBeenWhitelistByAdmin
userCurrentlyBlocked
}

# User has a blocked message existing in time window but the authentication time window is clear
message = "Policy evaluation has failed, user is currently blocked. Too many attempts or has reached failure limit" if {
withinPendingVsCompletedAuthLimit
withinTheAuthenticationFailureLimit
userCurrentlyBlocked
}

# Message for initial blocking of a user who is hitting failure limit without respective block event found
message = "Policy evaluation has failed with too many failed authentication attempts for user" if {
not withinTheAuthenticationFailureLimit
not hasBeenWhitelistByAdmin
not userCurrentlyBlocked
}

# Message for initial blocking of a user who is pending auth limit without respective block event found
message = "Policy evaluation has failed with too many pending authentication attempts found for user" if {
not withinPendingVsCompletedAuthLimit
not hasBeenWhitelistByAdmin
not userCurrentlyBlocked
}

# If a user has failed policy evaluation then check for existing user blocked event
# If no user blocked event exists then submit new actionEvent which holds record of when a user has failed evaluation
# This event is checked by future policy evaluations as well to enforce specific user blocked windows
actionEvent := {
"eventName": "ADAPT_POLICY_EVAL_USER_BLOCKED",
"eventTags": ["RISK_ENGINE", "ADAPT", "ADMIN"],
"machineUserName": input.events[0].machineUserName,
"isSuccessful": true,
} if {
not withinTheAuthenticationFailureLimit
not userCurrentlyBlocked
}

# If a user has failed policy evaluation then check for existing user blocked event
# If no user blocked event exists then submit new actionEvent which holds record of when a user has failed evaluation
# This event is checked by future policy evaluations as well to enforce specific user blocked windows
actionEvent := {
"eventName": "ADAPT_POLICY_EVAL_USER_BLOCKED",
"eventTags": ["RISK_ENGINE", "ADAPT", "ADMIN"],
"machineUserName": input.events[0].machineUserName,
"isSuccessful": true,
} if {
not withinPendingVsCompletedAuthLimit
not userCurrentlyBlocked
