# Example would be (timeDifferenceArray[3] < 2) -> Checks that the eventTime is within 2 HOURS of system time
checkTimeFrameForAuthFailures(eventTime) {
timeDifferenceArray = time.diff(eventTime, currentSystemTime)
timeDifferenceArray[1] < 2
}

# Perform all checks against event to ensure it will be counted if it contains 1) success=false 2) timestamp within given timeframe and 3) an event name we care about
check_against_configurations(event) {
# Converted event time from milliseconds to nanoseconds for proper comparison
eventTimeParsed = to_number(event.eventTimeInUTC)
eventTimeInNanoSeconds = (eventTimeParsed * 1000000)

# In order, check if the event is 1) a failure 2) within the timeframe configured AND 3) containing an authentication related event name
event.isSuccessful == false
checkTimeFrameForAuthFailures(eventTimeInNanoSeconds)

# List of AUTH event names separated into lists of their expected flow
oob_auth_events := ["OOB_WEBSITE_AUTH", "OOB_WEBSITE_TRANS"]
qr_auth_events := ["QR_FALLBACK_PAYLOAD_RETRIEVED", "SESSION_WEBSITE_AUTH"]
fido2_auth_events := ["FIDO2_WEBAUTHN", "SMARTKEY_AUTH"]

# Combine arrays based on allowedAuthenticators
qr_events := [e | e = qr_auth_events[_]; allowedAuthenticators[_] == "QR"]
fido2_events := [e | e = fido2_auth_events[_]; allowedAuthenticators[_] == "FIDO2"]

appendQREvents := array.concat(oob_auth_events, qr_events)
eventListReference := array.concat(appendQREvents, fido2_events)

containing_auth_event_name(event.eventName, eventListReference)
}

# Allow if the iterated events do not increase the failure counter higher than the limit specified in withinTheAuthenticationFailureLimit
allowed {
withinTheAuthenticationFailureLimit
}

message = "Policy evaluation successful" {
allowed
}

message = "Policy evaluation failed" {
not allowed
}",
    "testData": {
        "events": []
    }
}

